import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
assert.ok(process.argv.length === 2 || (process.argv.length === 3 && process.argv[2] === '--check'));
const expected =
    '// GENERATED by pi-cache/scripts/sync-internet-ais.mjs from utils/internetAis.ts. Do not edit.\n' +
    fs.readFileSync(path.join(root, 'utils/internetAis.ts'), 'utf8').replaceAll('\r\n', '\n');
for (const target of ['pi-cache/src/internetAisWire.ts', 'supabase/functions/_shared/internetAis.ts']) {
    const file = path.join(root, target);
    if (process.argv[2] === '--check')
        assert.equal(fs.readFileSync(file, 'utf8').replaceAll('\r\n', '\n'), expected, target);
    else fs.writeFileSync(file, expected);
}
